try:
    print('>>> f = hasattr')
    print('>>> x = (1, 2)')
    print('>>> y = type(1)')
    print('>>> f(x, y)')
    f = hasattr
    x = (1, 2)
    y = type(1)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
